function renderPrompt(template, vars = {}) {
  if (!template)
    return "";
  return template.replace(/\{\{(\w+)\}\}/g, (_match, key) => {
    const value = vars[key];
    return value === void 0 || value === null ? "" : String(value);
  });
}

